import { fileURLToPath } from "node:url";
import { defineConfig } from "vite";
import { sharedModules } from "../../shared/plugin.ts";

// Development: `vite` here, against a running `ludenea serve` (LUDENEA_SERVE, by default
// http://127.0.0.1:7878). Its WebSocket accepts only an `Origin` matching its `Host`, so the
// proxy presents both as the target's.
const target = process.env.LUDENEA_SERVE ?? "http://127.0.0.1:7878";
const proxied = { target, changeOrigin: true };

export default defineConfig({
  plugins: [sharedModules()],
  resolve: {
    // The renderer's files, generated by `pnpm -C editor build:render`: the built-ins import its
    // JavaScript and WebAssembly as URLs, to load a new instance of the module after a panic.
    alias: {
      "@ludenea/render-wasm": fileURLToPath(new URL("../../packages/render-wasm", import.meta.url)),
    },
  },
  server: {
    proxy: {
      "/ws/project": {
        ...proxied,
        ws: true,
        configure: (proxy) => proxy.on("proxyReqWs", (request) => request.setHeader("Origin", target)),
      },
      "/game": proxied,
      "/plugins": proxied,
    },
  },
});
